            setRooms((prev) => mergeRooms(prev, [payload]));
            break;
          case 'room:new':
            setRooms((prev) =>
              prev.some((r) => r.id === payload.id)
                ? prev
                : [...prev, { ...payload, effective_schedule: { interval: 5000, timeout: 15000 }, spark: [] }]
            );
            refreshStats();
            break;
          case 'room:remove':
            setRooms((prev) => prev.filter((r) => r.id !== payload.id));
            refreshStats();
            break;
          case 'alarm:new':
            setAlarms((a) => [payload.alarm, ...a]);
            setTasks((t) => [payload.task, ...t]);
            break;
          case 'alarm:update':
            setAlarms((a) => a.map((x) => (x.id === payload.id ? { ...x, ...payload } : x)));
            break;
          case 'alarm:escalate':
            setAlarms((a) =>
              a.map((x) =>
                x.id === payload.alarmId
